import { runQueryWithTenant, runQueriesWithTenant } from '@core/db';
import type {
  Account,
  OwnerType,
  Currency,
  AccountsSearchResult,
} from './account.types';

interface AccountRow {
  account_id: string;
  tenant_id: string;
  owner_id: string;
  owner_type: string;
  balance: string;
  currency: string;
  created_at: Date;
}

interface CountRow {
  total: string;
}

class AccountService {
  /**
   * Conversão LEGACY — saldo NÃO é verdade.
   * Qualquer uso de "balance" aqui é proibido como decisão.
   */
  private toAccount(row: AccountRow): Account {
    return {
      accountId: row.account_id,
      tenantId: row.tenant_id,
      ownerId: row.owner_id,
      ownerType: row.owner_type as OwnerType,
      balance: 0, // 🔴 saldo legado INVALIDADO por definição
      currency: row.currency as Currency,
      createdAt: row.created_at,
    };
  }

  // =====================================================
  // 🔴 MÉTODOS DE CRIAÇÃO — PROIBIDOS (GATE 3)
  // =====================================================

  async getOrCreateUserPrimaryAccount(): Promise<never> {
    throw new Error(
      '[GATE 3] Criação de contas financeiras LEGACY está PROIBIDA. Use Bank.'
    );
  }

  async createAccount(): Promise<never> {
    throw new Error(
      '[GATE 3] Criação de contas financeiras LEGACY está PROIBIDA. Use Bank.'
    );
  }

  async getOrCreateSystemAccount(): Promise<never> {
    throw new Error(
      '[GATE 3] Contas de sistema LEGACY estão PROIBIDAS. Use Bank.'
    );
  }

  // =====================================================
  // 🟡 MÉTODOS DE LEITURA — LEGACY / TRANSITÓRIOS
  // =====================================================

  async getAccountById(
    tenantId: string,
    accountId: string
  ): Promise<Account | null> {
    const row = await runQueryWithTenant<AccountRow>(
      tenantId,
      {
        text: `
          SELECT account_id, tenant_id, owner_id, owner_type, balance, currency, created_at
          FROM accounts
          WHERE account_id = $1
          LIMIT 1
        `,
        values: [accountId],
      }
    );

    return row ? this.toAccount(row) : null;
  }

  async getAccountsByOwner(
    tenantId: string,
    ownerId: string,
    ownerType: OwnerType
  ): Promise<Account[]> {
    const rows = await runQueriesWithTenant<AccountRow>(
      tenantId,
      {
        text: `
          SELECT account_id, tenant_id, owner_id, owner_type, balance, currency, created_at
          FROM accounts
          WHERE owner_id = $1 AND owner_type = $2
          ORDER BY created_at DESC
        `,
        values: [ownerId, ownerType],
      }
    );

    return rows.map((r) => this.toAccount(r));
  }

  /**
   * ⚠️ LEGACY TRANSITÓRIO (CONDENADO)
   * Este método existe apenas por compatibilidade temporária.
   *
   * Regras:
   * - NÃO usar para decisão
   * - NÃO usar para fluxo crítico (pagamento, liberação, bloqueio)
   * - Será removido no Gate 5
   */
  async listAccounts(
    tenantId: string,
    options: { limit?: number; offset?: number; ownerType?: OwnerType } = {}
  ): Promise<AccountsSearchResult> {
    const { limit = 50, offset = 0, ownerType } = options;

    let sql = `
      SELECT account_id, tenant_id, owner_id, owner_type, balance, currency, created_at
      FROM accounts
    `;

    const params: unknown[] = [];

    if (ownerType) {
      sql += ` WHERE owner_type = $1`;
      params.push(ownerType);
    }

    sql += ` ORDER BY created_at DESC LIMIT $${params.length + 1} OFFSET $${params.length + 2}`;
    params.push(limit, offset);

    const rows = await runQueriesWithTenant<AccountRow>(tenantId, {
      text: sql,
      values: params,
    });

    // ⚠️ COUNT em legacy: permitido apenas para UI/transição (não decisório).
    const countRow = await runQueryWithTenant<CountRow>(
      tenantId,
      {
        text: ownerType
          ? `SELECT COUNT(*) AS total FROM accounts WHERE owner_type = $1`
          : `SELECT COUNT(*) AS total FROM accounts`,
        values: ownerType ? [ownerType] : [],
      }
    );

    return {
      accounts: rows.map((r) => this.toAccount(r)),
      total: countRow ? Number(countRow.total) : 0,
    };
  }

  // =====================================================
  // 🔴 LEITURA DECISÓRIA — PROIBIDA
  // =====================================================

  async accountExists(): Promise<never> {
    throw new Error(
      '[GATE 3] accountExists() em accounts LEGACY é proibido para decisão.'
    );
  }

  // =====================================================
  // 🔴 SALDO — PROIBIDO
  // =====================================================

  async getBalance(): Promise<never> {
    throw new Error('[GATE 3] Saldo LEGACY é inválido. Use bank_ledger.');
  }

  // =====================================================
  // 🟡 Compatibilidade: métodos antigos por global_user_id
  // (mantidos como no original: retorno vazio)
  // =====================================================

  async getAccountsByGlobalUserId(): Promise<Account[]> {
    return [];
  }

  async getPrimaryAccountByGlobalUserId(): Promise<Account | null> {
    return null;
  }
}

export const accountService = new AccountService();